CREATE FUNCTION public.admin_operational_stats() RETURNS jsonb LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT jsonb_build_object('users',(SELECT count(*) FROM public.profiles),'active_users',(SELECT count(*) FROM public.profiles WHERE account_status='active'),'suspended_users',(SELECT count(*) FROM public.profiles WHERE account_status='suspended'),'shipments',(SELECT count(*) FROM public.shipments),'pending',(SELECT count(*) FROM public.shipments WHERE status IN ('Shipment Registered','Processing','Picked Up') AND cancelled_at IS NULL),'in_transit',(SELECT count(*) FROM public.shipments WHERE status IN ('In Transit','Arrived at Sorting Facility','Out for Delivery') AND cancelled_at IS NULL),'delivered',(SELECT count(*) FROM public.shipments WHERE status='Delivered' AND cancelled_at IS NULL),'delayed',(SELECT count(*) FROM public.shipments WHERE status='Exception / Delayed' AND cancelled_at IS NULL),'revenue',(SELECT coalesce(sum(amount),0) FROM public.payment_records WHERE status='paid' AND verified_at IS NOT NULL AND currency=coalesce((SELECT currency FROM public.admin_settings LIMIT 1),'USD')),'pending_payments',(SELECT count(*) FROM public.payment_records WHERE status='pending'),'support_open',(SELECT count(*) FROM public.service_requests WHERE kind='contact' AND status IN ('received','pending')),'months',(SELECT coalesce(jsonb_agg(x ORDER BY x.month),'[]'::jsonb) FROM (SELECT to_char(date_trunc('month',created_at),'YYYY-MM') AS "month",count(*) AS total,count(*) FILTER(WHERE status='Delivered' AND cancelled_at IS NULL) AS delivered,count(*) FILTER(WHERE status='Exception / Delayed' AND cancelled_at IS NULL) AS delayed FROM public.shipments GROUP BY 1) x),'destinations',(SELECT coalesce(jsonb_agg(x),'[]'::jsonb) FROM (SELECT destination,count(*) AS total FROM public.shipments GROUP BY destination ORDER BY count(*) DESC LIMIT 10) x)) $$;
REVOKE ALL ON FUNCTION public.admin_operational_stats() FROM PUBLIC,anon,authenticated; GRANT EXECUTE ON FUNCTION public.admin_operational_stats() TO service_role;